"""Temperature conversion helpers."""


def celsius_to_fahrenheit(c):
    # BUG #1: the +32 offset is missing.
    return c * 9 / 5


def fahrenheit_to_celsius(f):
    return (f - 32) * 5 / 9

"""Money helpers."""


def cents_to_dollars(cents):
    return cents / 100


def apply_tax(amount, rate):
    """Apply a tax rate (e.g. 0.07) and round to whole cents."""
    # BUG #3: int() truncates instead of rounding, losing a cent.
    return int(amount * (1 + rate) * 100) / 100


def format_currency(amount):
    """Format a number as US currency, e.g. 1234.5 -> '$1,234.50'."""
    # BUG #4: no thousands separator and no fixed 2-decimal formatting.
    return "$" + str(round(amount, 2))

"""Validation helpers."""

import re


def is_valid_email(email):
    """A pragmatic email check: one @, and a dotted domain."""
    # BUG #6: the domain is not required to contain a dot, so "a@b" passes.
    return bool(re.match(r"^[^@\s]+@[^@\s]+$", email))

"""String helpers.

NOTE: `normalize` is a SHARED helper used by both `is_palindrome` and
`slugify`. `slugify` relies on `normalize` keeping internal spaces so it can
turn them into hyphens. Changing `normalize` to fix the palindrome bug will
break slugify's (currently passing) test — the correct fix is local to
`is_palindrome`.
"""


def normalize(text):
    return text.strip()


def is_palindrome(s):
    # BUG #7: should ignore case, spaces, and punctuation.
    n = normalize(s)
    return n == n[::-1]


def slugify(title):
    # Correct and currently passing — must STAY passing.
    return normalize(title).replace(" ", "-").lower()

