"""Workspace: an isolated copy of the target repo the agent edits, plus the
pytest runner and the file tools. Also tracks a per-file edit history so the
agent can revert a change that introduced a regression.
"""

from __future__ import annotations

import json
import os
import shutil
import subprocess
import sys
import tempfile
from dataclasses import dataclass, field


@dataclass
class TestResult:
    passed: list[str]
    failed: list[str]
    errors: str  # short failure digest for the model
    raw: str     # full pytest output (kept for logs, not sent to the model)

    @property
    def num_passed(self) -> int:
        return len(self.passed)

    @property
    def num_failed(self) -> int:
        return len(self.failed)


class Workspace:
    """An isolated working copy of `source_repo` under a temp dir."""

    def __init__(self, source_repo: str):
        self.source_repo = os.path.abspath(source_repo)
        self.root = tempfile.mkdtemp(prefix="fixpoint_ws_")
        self.repo = os.path.join(self.root, "repo")
        shutil.copytree(self.source_repo, self.repo)
        # per-file undo stack: path -> [older, ..., current]
        self._history: dict[str, list[str]] = {}
        self.baseline_passing: set[str] = set()
        self.baseline_failing: set[str] = set()

    # ---- lifecycle -------------------------------------------------------
    def capture_baseline(self) -> TestResult:
        res = self.run_tests()
        self.baseline_passing = set(res.passed)
        self.baseline_failing = set(res.failed)
        return res

    def cleanup(self):
        shutil.rmtree(self.root, ignore_errors=True)

    # ---- helpers ---------------------------------------------------------
    def _abs(self, path: str) -> str:
        p = os.path.normpath(os.path.join(self.repo, path))
        if not p.startswith(self.repo):
            raise ValueError(f"path escapes workspace: {path}")
        return p

    def list_files(self) -> list[str]:
        out = []
        for dirpath, dirnames, filenames in os.walk(self.repo):
            dirnames[:] = [d for d in dirnames if d not in {"__pycache__", ".pytest_cache", ".git"}]
            for fn in filenames:
                if fn.endswith((".pyc",)):
                    continue
                rel = os.path.relpath(os.path.join(dirpath, fn), self.repo)
                out.append(rel.replace(os.sep, "/"))
        return sorted(out)

    def read_file(self, path: str) -> str:
        with open(self._abs(path), "r", encoding="utf-8") as f:
            return f.read()

    def _snapshot(self, path: str):
        """Record current content on the undo stack before a change."""
        abs_p = self._abs(path)
        current = ""
        if os.path.exists(abs_p):
            with open(abs_p, "r", encoding="utf-8") as f:
                current = f.read()
        self._history.setdefault(path, []).append(current)

    def write_file(self, path: str, content: str) -> str:
        self._snapshot(path)
        abs_p = self._abs(path)
        os.makedirs(os.path.dirname(abs_p), exist_ok=True)
        with open(abs_p, "w", encoding="utf-8", newline="\n") as f:
            f.write(content)
        return f"wrote {len(content)} bytes to {path}"

    def edit_file(self, path: str, old: str, new: str) -> str:
        content = self.read_file(path)
        count = content.count(old)
        if count == 0:
            raise ValueError(
                f"`old` string not found in {path}. Read the file again and copy the exact text."
            )
        if count > 1:
            raise ValueError(
                f"`old` string is not unique in {path} ({count} matches). Include more surrounding context."
            )
        self._snapshot(path)
        abs_p = self._abs(path)
        with open(abs_p, "w", encoding="utf-8", newline="\n") as f:
            f.write(content.replace(old, new, 1))
        return f"edited {path} (1 replacement)"

    def revert_file(self, path: str) -> str:
        hist = self._history.get(path)
        if not hist:
            return f"nothing to revert for {path}"
        previous = hist.pop()
        abs_p = self._abs(path)
        with open(abs_p, "w", encoding="utf-8", newline="\n") as f:
            f.write(previous)
        return f"reverted {path} to its previous version"

    # ---- test runner -----------------------------------------------------
    def run_tests(self) -> TestResult:
        report_path = os.path.join(self.root, "report.json")
        cmd = [
            sys.executable, "-m", "pytest", "-q",
            "--no-header", "-p", "no:cacheprovider",
            f"--junitxml={os.path.join(self.root, 'junit.xml')}",
        ]
        proc = subprocess.run(
            cmd, cwd=self.repo, capture_output=True, text=True, timeout=120
        )
        raw = proc.stdout + "\n" + proc.stderr
        passed, failed = self._parse_junit(os.path.join(self.root, "junit.xml"))
        errors = self._digest_failures(raw)
        return TestResult(passed=passed, failed=failed, errors=errors, raw=raw)

    @staticmethod
    def _parse_junit(xml_path: str):
        import xml.etree.ElementTree as ET

        passed, failed = [], []
        if not os.path.exists(xml_path):
            return passed, failed
        tree = ET.parse(xml_path)
        for case in tree.iter("testcase"):
            cls = case.get("classname", "")
            name = case.get("name", "")
            nodeid = f"{cls}::{name}" if cls else name
            is_fail = any(child.tag in ("failure", "error") for child in case)
            (failed if is_fail else passed).append(nodeid)
        return passed, failed

    @staticmethod
    def _digest_failures(raw: str) -> str:
        """Keep the concise pytest 'short test summary info' section."""
        lines = raw.splitlines()
        out = []
        capture = False
        for ln in lines:
            if "short test summary info" in ln:
                capture = True
            if capture:
                out.append(ln)
        if not out:
            # fall back to the tail
            out = lines[-25:]
        return "\n".join(out).strip()

"""Model prices ($ per 1M tokens) so we can turn token usage into dollars.

Source: Anthropic API pricing (first-party rates). Update as needed.
"""

PRICES = {
    "claude-opus-5-5":   {"input": 4.00,  "output": 20.00, "cache_read": 0.20},
    "claude-opus-5":     {"input": 5.00,  "output": 25.00, "cache_read": 0.50},
    "claude-sonnet-5-5": {"input": 2.00,  "output": 10.00, "cache_read": 0.20},
    "claude-haiku-5-5":  {"input": 0.10,  "output": 0.50,  "cache_read": 0.01},
}

# Fallback if an unknown model id is used.
_DEFAULT = {"input": 4.00, "output": 20.00, "cache_read": 0.20}


def cost_usd(model: str, input_tokens: int, output_tokens: int,
             cache_read_tokens: int = 0) -> float:
    p = PRICES.get(model, _DEFAULT)
    billable_input = max(input_tokens - cache_read_tokens, 0)
    return (
        billable_input / 1_000_000 * p["input"]
        + cache_read_tokens / 1_000_000 * p["cache_read"]
        + output_tokens / 1_000_000 * p["output"]
    )

"""Repo map = the codebase context Fixpoint v2 feeds the agent.

In the real pipeline this comes from **Entire Graph** (`entire graph init-agents`
writes `.entire/graph-agent.md`, `AGENTS.md`, `CLAUDE.md`). If one of those files
is present in the target repo we use it directly — that is the Entire integration.

If it is not present (e.g. Entire CLI not installed on this machine), we fall
back to a lightweight map generated by parsing the Python files with `ast`, so
the v1/v2 comparison still runs. Which source was used is recorded in the run
metrics for the submission.
"""

from __future__ import annotations

import ast
import os

ENTIRE_FILES = [".entire/graph-agent.md", "AGENTS.md", "CLAUDE.md"]


def load_repo_map(repo_dir: str) -> tuple[str, str]:
    """Return (map_text, source) where source is 'entire-graph' or 'ast-fallback'."""
    for rel in ENTIRE_FILES:
        p = os.path.join(repo_dir, rel)
        if os.path.exists(p):
            with open(p, "r", encoding="utf-8") as f:
                text = f.read().strip()
            if text:
                return text, f"entire-graph ({rel})"
    return _ast_map(repo_dir), "ast-fallback"


def _ast_map(repo_dir: str) -> str:
    lines = ["# Repo map (symbols)", ""]
    for dirpath, dirnames, filenames in os.walk(repo_dir):
        dirnames[:] = [d for d in dirnames if d not in {"__pycache__", ".pytest_cache", ".git"}]
        for fn in sorted(filenames):
            if not fn.endswith(".py"):
                continue
            rel = os.path.relpath(os.path.join(dirpath, fn), repo_dir).replace(os.sep, "/")
            if rel.startswith("tests/") or fn == "conftest.py":
                continue
            try:
                src = open(os.path.join(dirpath, fn), "r", encoding="utf-8").read()
                tree = ast.parse(src)
            except (OSError, SyntaxError):
                continue
            syms = []
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    args = ", ".join(a.arg for a in node.args.args)
                    doc = ast.get_docstring(node) or ""
                    doc = doc.splitlines()[0] if doc else ""
                    syms.append(f"  - {node.name}({args}){f' — {doc}' if doc else ''}")
            if syms:
                lines.append(f"`{rel}`")
                lines.extend(syms)
                lines.append("")
    return "\n".join(lines).strip()

