"""Build a self-contained HTML report from runs/v1.json + runs/v2.json.

    python report.py            # -> docs/report.html  (open in any browser)

No server, no external libraries — safe to commit and share.
"""

import html
import json
import os

ACTION_ICON = {
    "run_tests": "▶", "read_file": "👁", "list_files": "📂",
    "write_file": "✎", "edit_file": "✎", "revert_file": "↩",
    "success": "✅", "stop": "⏹",
}


def load(path):
    with open(path, encoding="utf-8") as f:
        return json.load(f)


def card(m):
    ok = m.get("success")
    status = "PASS" if ok else "INCOMPLETE"
    status_cls = "ok" if ok else "bad"
    rows = [
        ("Tests fixed", f"{m['tests_fixed']} / {m['baseline_failed']}"),
        ("Regressions left behind", m["regressions_remaining"]),
        ("Regressions caught → reverted", f"{m['regressions_encountered']} → {m['reverts']}"),
        ("Steps", m["steps"]),
        ("Input tokens", f"{m['input_tokens']:,}"),
        ("Output tokens", f"{m['output_tokens']:,}"),
        ("Cost (USD)", f"${m['cost_usd']:.4f}"),
        ("Wall time", f"{m['wall_seconds']}s"),
    ]
    tr = "".join(f"<tr><td>{html.escape(k)}</td><td>{html.escape(str(v))}</td></tr>" for k, v in rows)
    sub = "baseline" if m["variant"] == "v1" else "Entire-Graph context + verify-and-revert"
    return f"""
    <div class="card">
      <div class="card-h">
        <h2>{m['variant']} <span class="sub">{html.escape(sub)}</span></h2>
        <span class="badge {status_cls}">{status}</span>
      </div>
      <table>{tr}</table>
    </div>"""


def timeline(m):
    items = []
    for ev in m.get("timeline", []):
        act = ev.get("action", "")
        icon = ACTION_ICON.get(act, "•")
        detail = html.escape(ev.get("detail") or "")
        cls = ""
        note = ""
        if act == "revert_file":
            cls, note = "recover", " — recovery: backing out a regression"
        elif act == "success":
            cls = "ok-row"
        elif ev.get("error"):
            cls = "err-row"
        items.append(
            f'<li class="{cls}"><span class="st">{ev.get("step","")}</span>'
            f'<span class="ic">{icon}</span>'
            f'<span class="ac">{html.escape(act)}</span>'
            f'<span class="dt">{detail}{note}</span></li>'
        )
    return "<ul class='timeline'>" + "".join(items) + "</ul>"


def before_after(v1, v2):
    def pct(a, b):
        return f"{(a-b)/a*100:+.0f}%" if a else "—"
    rows = [
        ("Tests fixed", f"{v1['tests_fixed']}/{v1['baseline_failed']}", f"{v2['tests_fixed']}/{v2['baseline_failed']}", ""),
        ("All green", str(v1["success"]), str(v2["success"]), ""),
        ("Regressions left", v1["regressions_remaining"], v2["regressions_remaining"], ""),
        ("Steps", v1["steps"], v2["steps"], pct(v1["steps"], v2["steps"])),
        ("Input tokens", f"{v1['input_tokens']:,}", f"{v2['input_tokens']:,}", pct(v1["input_tokens"], v2["input_tokens"])),
        ("Cost (USD)", f"${v1['cost_usd']:.4f}", f"${v2['cost_usd']:.4f}", pct(v1["cost_usd"], v2["cost_usd"])),
    ]
    tr = "".join(
        f"<tr><td>{html.escape(n)}</td><td>{html.escape(str(a))}</td>"
        f"<td>{html.escape(str(b))}</td><td class='chg'>{html.escape(str(c))}</td></tr>"
        for n, a, b, c in rows
    )
    return f"""<table class="ba"><thead><tr><th>Metric</th><th>v1 baseline</th>
      <th>v2 improved</th><th>change</th></tr></thead><tbody>{tr}</tbody></table>"""


def main():
    v1, v2 = load("runs/v1.json"), load("runs/v2.json")
    simulated = "simulated" in (v1.get("mode"), v2.get("mode"))
    banner = ("<div class='warn'>⚠ SIMULATED run (no LLM). Behavior and recovery are real; "
              "token/cost figures are synthetic estimates — replace with a live run for submission."
              "</div>") if simulated else ""
    diff = html.escape(v2.get("final_diff", "") or "(no diff captured)")

    doc = f"""<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Fixpoint Report</title>
<style>
:root{{--bg:#f7f8fa;--fg:#1a1d23;--muted:#5b6472;--card:#fff;--line:#e4e7ec;
--ok:#0f9d58;--bad:#d93025;--accent:#4f46e5;--recover:#b36b00;--code:#f0f1f4;}}
:root:not([data-theme=light]) @media (prefers-color-scheme:dark){{}}
@media (prefers-color-scheme:dark){{:root:not([data-theme=light]){{
--bg:#0f1115;--fg:#e6e8ec;--muted:#9aa4b2;--card:#171a21;--line:#272b33;
--ok:#39d98a;--bad:#ff6b6b;--accent:#8b85ff;--recover:#ffb259;--code:#1d2129;}}}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--fg);
font:15px/1.5 -apple-system,Segoe UI,Roboto,sans-serif;padding:24px 16px}}
.wrap{{max-width:900px;margin:0 auto}}h1{{margin:0 0 4px;font-size:26px}}
.lead{{color:var(--muted);margin:0 0 20px}}
.warn{{background:color-mix(in srgb,var(--recover) 18%,transparent);
border:1px solid var(--recover);color:var(--fg);padding:10px 14px;border-radius:10px;margin-bottom:18px;font-size:13px}}
.grid{{display:grid;grid-template-columns:1fr 1fr;gap:16px}}
@media(max-width:640px){{.grid{{grid-template-columns:1fr}}}}
.card{{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:16px}}
.card-h{{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}}
.card h2{{margin:0;font-size:20px}}.sub{{display:block;font-size:12px;color:var(--muted);font-weight:400}}
.badge{{font-size:12px;font-weight:700;padding:3px 10px;border-radius:999px}}
.badge.ok{{background:color-mix(in srgb,var(--ok) 18%,transparent);color:var(--ok)}}
.badge.bad{{background:color-mix(in srgb,var(--bad) 18%,transparent);color:var(--bad)}}
table{{width:100%;border-collapse:collapse;font-size:13px}}
td,th{{padding:6px 8px;border-bottom:1px solid var(--line);text-align:left}}
td:last-child,th:last-child{{text-align:right}}
h3{{margin:26px 0 10px;font-size:17px}}
.ba .chg{{font-weight:700;color:var(--accent)}}
.timeline{{list-style:none;margin:0;padding:0;border:1px solid var(--line);border-radius:12px;overflow:hidden}}
.timeline li{{display:flex;gap:10px;align-items:center;padding:7px 12px;border-bottom:1px solid var(--line);font-size:13px}}
.timeline li:last-child{{border-bottom:0}}
.timeline .st{{width:22px;color:var(--muted);text-align:right}}
.timeline .ic{{width:18px;text-align:center}}
.timeline .ac{{width:92px;font-weight:600}}
.timeline .dt{{color:var(--muted)}}
.timeline li.recover{{background:color-mix(in srgb,var(--recover) 14%,transparent)}}
.timeline li.recover .dt{{color:var(--recover);font-weight:600}}
.timeline li.ok-row{{background:color-mix(in srgb,var(--ok) 12%,transparent)}}
pre{{background:var(--code);border:1px solid var(--line);border-radius:10px;padding:12px;overflow:auto;font-size:12px}}
details{{margin-top:10px}}summary{{cursor:pointer;color:var(--accent)}}
.foot{{color:var(--muted);font-size:12px;margin-top:28px}}
</style></head><body><div class="wrap">
<h1>Fixpoint — self-healing test agent</h1>
<p class="lead">neatHack 2026 · team AI LONE STAR · red→green with autonomous recovery</p>
{banner}
<div class="grid">{card(v1)}{card(v2)}</div>
<h3>Before / after</h3>
{before_after(v1, v2)}
<h3>v2 timeline — the recovery is highlighted</h3>
{timeline(v2)}
<h3>What v2 changed</h3>
<details><summary>show unified diff</summary><pre>{diff}</pre></details>
<p class="foot">Generated by <code>report.py</code>. Open <code>runs/*.json</code> for raw metrics.</p>
</div></body></html>"""

    os.makedirs("docs", exist_ok=True)
    out = os.path.join("docs", "report.html")
    with open(out, "w", encoding="utf-8") as f:
        f.write(doc)
    print(f"wrote {out}")


if __name__ == "__main__":
    main()

"""Synthetic seed data for Invoicely. All values are fake.

Two tenants, three users (two share a tenant so we can tell tenant-scoped access
apart from owner-only access), and one invoice per user.
"""

from __future__ import annotations

import copy

# token -> user_id   (fixture-only bearer tokens; NOT real secrets)
_TOKENS = {
    "tok-alice": "alice",
    "tok-bob": "bob",
    "tok-carol": "carol",
}

_USERS = {
    "alice": {"id": "alice", "tenant_id": "t1"},
    "bob": {"id": "bob", "tenant_id": "t1"},   # same tenant as alice
    "carol": {"id": "carol", "tenant_id": "t2"},
}

_INVOICES = {
