"""Model prices ($ per 1M tokens) to turn token usage into a cost per fix."""

PRICES = {
    "claude-opus-5-5":   {"input": 4.00, "output": 20.00},
    "claude-sonnet-5-5": {"input": 2.00, "output": 10.00},
    "claude-haiku-5-5":  {"input": 0.10, "output": 0.50},
}
_DEFAULT = {"input": 2.00, "output": 10.00}


def cost_usd(model, input_tokens, output_tokens):
    p = PRICES.get(model, _DEFAULT)
    return round(input_tokens / 1e6 * p["input"] + output_tokens / 1e6 * p["output"], 6)

"""Render a self-contained HTML report from a TenantGuard run.

    python report.py                # newest run in artifacts/
    python report.py run-1234abcd   # a specific run

Writes docs/report.html (no server, no external libs).
"""

import glob
import html
import json
import os
import sys

PHASE_ICON = {
    "intake": "•", "baseline_tests": "▶", "inspect_code": "👁",
    "propose_patch": "✎", "apply_in_worktree": "�4", "apply_failed": "✖",
    "verify": "✔", "classify_failure": "↩", "export_report": "✅",
    "human_review": "⚑",
}


def pick_report(arg):
    if arg:
        return os.path.join("artifacts", arg, "report.json")
    reports = glob.glob("artifacts/*/report.json")
    if not reports:
        sys.exit("no runs in artifacts/. Run: python run_case.py")
    return max(reports, key=os.path.getmtime)


def row_class(phase, detail):
    if phase == "classify_failure":
        return "recover"
    if phase == "verify" and "regressed" in detail:
        return "warn-row"
    if phase == "verify" and "fixed" in detail:
        return "ok-row"
    if phase in ("export_report",):
        return "ok-row"
    if phase in ("apply_failed", "human_review"):
        return "err-row"
    return ""


def main():
    rp = pick_report(sys.argv[1] if len(sys.argv) > 1 else None)
    d = json.load(open(rp, encoding="utf-8"))
    run_dir = os.path.dirname(rp)
    diff = ""
    dp = os.path.join(run_dir, "patch.diff")
    if os.path.exists(dp):
        diff = open(dp, encoding="utf-8").read()

    v = d.get("verdict") or {}
    llm = d.get("llm")
    fixed = d["status"] == "fixed"

    timeline = []
    for e in d["events"]:
        ph, dt = e["phase"], e.get("detail", "")
        icon = PHASE_ICON.get(ph, "•")
        extra = " — recovery: reverted the regressing patch" if ph == "classify_failure" else ""
        timeline.append(
            f'<li class="{row_class(ph, dt)}"><span class="ic">{icon}</span>'
            f'<span class="ph">{html.escape(ph)}</span>'
            f'<span class="dt">{html.escape(dt)}{extra}</span></li>'
        )

    sec = "✅ pass" if v.get("security_pass") else "❌ fail"
    fun = "✅ pass" if v.get("functionality_pass") else "❌ fail"
    regressed = v.get("regressions") or []
    llm_rows = ""
    if llm:
        cost = f"${llm['cost_usd']:.4f}" if llm.get("cost_usd") is not None else "—"
        llm_rows = (f"<tr><td>Model</td><td>{html.escape(str(llm.get('model')))}</td></tr>"
                    f"<tr><td>Prompt quality</td><td>{html.escape(str(llm.get('quality')))}</td></tr>"
                    f"<tr><td>Tokens (in/out)</td><td>{llm.get('input_tokens',0):,} / {llm.get('output_tokens',0):,}</td></tr>"
                    f"<tr><td>Cost per fix</td><td>{cost}</td></tr>"
                    f"<tr><td>neatlogs traced</td><td>{llm.get('neatlogs')}</td></tr>")
    else:
        llm_rows = '<tr><td>Brain</td><td>offline-scripted (no LLM) — token/cost from the live run</td></tr>'

    doc = f"""<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>TenantGuard Report</title>
<style>
:root{{--bg:#f6f7f9;--fg:#15181e;--muted:#5b6472;--card:#fff;--line:#e3e6eb;
--ok:#0f9d58;--bad:#d93025;--warn:#b36b00;--accent:#4f46e5;--code:#eef0f4;}}
