--ok:#39d98a;--bad:#ff6b6b;--warn:#ffb259;--accent:#8b85ff;--code:#1c2029;}}}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--fg);
font:15px/1.55 -apple-system,Segoe UI,Roboto,sans-serif;padding:24px 16px}}
.wrap{{max-width:860px;margin:0 auto}}h1{{margin:0 0 2px;font-size:25px}}
