<span class="pill {'ok' if fixed else 'bad'}">{'FIXED' if fixed else d['status'].upper()}</span>

<div class="cards">
  <div class="card"><h3>Outcome</h3><table>
    <tr><td>Status</td><td>{html.escape(d['status'])}</td></tr>
    <tr><td>Patch attempts</td><td>{d['attempts']}</td></tr>
    <tr><td>Security tests</td><td>{sec}</td></tr>
    <tr><td>Functionality tests</td><td>{fun}</td></tr>
    <tr><td>Regression during run</td><td>{'yes → recovered' if any('regressed' in e.get('detail','') for e in d['events']) else 'no'}</td></tr>
    <tr><td>Wall time</td><td>{d.get('wall_seconds')}s</td></tr>
  </table></div>
  <div class="card"><h3>Model / cost</h3><table>{llm_rows}</table></div>
</div>

<h2>Phase timeline — the recovery is highlighted</h2>
<ul class="tl">{''.join(timeline)}</ul>

<h2>The patch it applied</h2>
<pre>{_fmt_diff(diff)}</pre>

<p class="foot">Generated by <code>report.py</code> from <code>{html.escape(rp)}</code>.
Security = cross-tenant access denied; Functionality = legitimate same-tenant access preserved.
Both must pass for success.</p>
</div></body></html>"""

    os.makedirs("docs", exist_ok=True)
    out = os.path.join("docs", "report.html")
    open(out, "w", encoding="utf-8").write(doc)
    print(f"wrote {out} (from {rp})")


def _fmt_diff(diff):
    if not diff:
        return "(no diff)"
    lines = []
    for ln in diff.splitlines():
        esc = html.escape(ln)
        if ln.startswith("+") and not ln.startswith("+++"):
            lines.append(f'<span class="ins">{esc}</span>')
        elif ln.startswith("-") and not ln.startswith("---"):
            lines.append(f'<span class="del">{esc}</span>')
        else:
            lines.append(esc)
    return "\n".join(lines)


