def main():
    args = [a for a in sys.argv[1:]]
    site = "--site" in args
    args = [a for a in args if a != "--site"]
    rp = pick_report(args[0] if args else None)
    d = json.load(open(rp, encoding="utf-8"))
    run_dir = os.path.dirname(rp)
    diff = ""
    dp = os.path.join(run_dir, "patch.diff")
    if os.path.exists(dp):
        diff = open(dp, encoding="utf-8").read()

    if site:
        os.makedirs("site", exist_ok=True)
        open("site/index.html", "w", encoding="utf-8").write(page_external(d, diff))
        open("site/styles.css", "w", encoding="utf-8").write(STYLE + "\n")
        open("site/app.js", "w", encoding="utf-8").write(SCRIPT + "\n")
        print(f"wrote site/ (index.html, styles.css, app.js) from {rp}")
    else:
        os.makedirs("docs", exist_ok=True)
        open("docs/report.html", "w", encoding="utf-8").write(page_inline(d, diff))
        print(f"wrote docs/report.html (from {rp})")


if __name__ == "__main__":
    main()

